<script setup>
import {ref,onMounted} from 'vue';import PageHeader from '../../components/student/PageHeader.vue';import {studentApi} from '../../services/studentApi'
const items=ref([]),loading=ref(true),error=ref(''),busy=ref(null);onMounted(async()=>{try{const r=await studentApi.getAssignments();items.value=r.data?.assignments||[]}catch(e){error.value=e.message}finally{loading.value=false}})
async function progress(a,p){busy.value=a.id;try{await studentApi.updateAssignmentProgress(a.id,p);const r=await studentApi.getAssignments();items.value=r.data?.assignments||[]}catch(e){alert(e.message)}finally{busy.value=null}}
</script>
<template><div><PageHeader title="Interactive Assignments" subtitle="Assignments from your tutor, stored in the database."/><p v-if="loading">Loading assignments...</p><p v-else-if="error" class="text-red-500">{{error}}</p><div v-else-if="!items.length" class="card p-8 text-center text-slate-500">No assignments yet.</div><div v-else class="grid grid-cols-1 md:grid-cols-2 gap-4"><div v-for="a in items" :key="a.id" class="card p-5"><div class="flex justify-between"><div><p class="text-xs text-brand-blue">{{a.subject}}</p><h3 class="font-display font-bold">{{a.title}}</h3></div><span class="text-xs">{{a.status}}</span></div><p class="text-sm text-slate-500 mt-2">{{a.description}}</p><p class="text-xs mt-2">Due: {{a.dueDate||'No due date'}}</p><div class="h-2 bg-slate-100 rounded mt-4 overflow-hidden"><div class="h-full bg-brand-blue" :style="{width:`${a.progress}%`}"></div></div><div class="flex gap-2 mt-4"><button class="btn sm" :disabled="busy===a.id" @click="progress(a,Math.min(100,a.progress+25))">Update progress</button><button class="btn grad sm" :disabled="busy===a.id" @click="progress(a,100)">Submit</button></div></div></div></div></template>
